// Qualification-only scene script. Loaded exclusively in the generated synthetic Creator project.
const fs=require('fs');const path=require('path');
const cc=require('cc');
const serialize=object=>{const fn=globalThis.EditorExtends?.serialize||globalThis.cce?.Utils?.serialize;if(typeof fn!=='function')throw Error('Editor serializer unavailable');const result=fn(object);return typeof result==='string'?result:JSON.stringify(result);};
function check(prefab,x){const root=prefab.data;const child=root.children[0];if(root.name!=='Root'||child?.name!=='Child'||root.position.x!==x||root.position.y!==2||root.position.z!==3)throw Error('Node values were not preserved');if(root.getComponent(cc.Button).target!==child)throw Error('Component target binding lost');return {rootId:root.uuid,childId:child.uuid,position:{x:root.position.x,y:root.position.y,z:root.position.z},buttonTarget:child.name};}
exports.methods={
 createFixture(dir){fs.mkdirSync(dir,{recursive:true});const root=new cc.Node('Root');const child=new cc.Node('Child');root.addChild(child);root.setPosition(1,2,3);root.addComponent(cc.UITransform);const button=root.addComponent(cc.Button);button.target=child;const prefab=new cc.Prefab();prefab.data=root;const text=serialize(prefab);fs.writeFileSync(path.join(dir,'native-original.prefab'),text);return {version:cc.ENGINE_VERSION||cc.VERSION||null,before:check(prefab,1),serializer:'EditorExtends.serialize / cce.Utils.serialize'};},
 verify(dir){const load=name=>cc.deserialize(JSON.parse(fs.readFileSync(path.join(dir,name),'utf8')));const before=load('native-original.prefab'),after=load('native-restored.prefab');const initial=check(before,1),restored=check(after,99);if(initial.rootId!==restored.rootId||initial.childId!==restored.childId)throw Error('Native node identities changed');fs.writeFileSync(path.join(dir,'native-saved.prefab'),serialize(after));const reloaded=check(load('native-saved.prefab'),99);if(reloaded.rootId!==initial.rootId||reloaded.childId!==initial.childId)throw Error('Identity changed after Editor save/reload');return {initial,restored,reloaded,deserialize:true,editorSerialize:true,diskReload:true};}
};
